import re
from datetime import datetime

_ANGLE_RE = re.compile(r"<([^<>]*)>")
_EXT_RE = re.compile(r"ext|x|#", re.IGNORECASE)
_ZIP4_RE = re.compile(r"([0-9]{4,5})-[0-9]{4}")
_DATE_FORMATS = ("%Y-%m-%d", "%m/%d/%Y", "%Y-%m-%dT%H:%M:%S")


def _get(row, key):
    value = row.get(key)
    return "" if value is None else str(value)


def _is_ascii_digits(s):
    return bool(s) and all("0" <= c <= "9" for c in s)


def _normalize_email(raw):
    s = raw
    m = _ANGLE_RE.search(s)
    if m:
        s = m.group(1)
    s = s.strip().lower()
    if s.count("@") == 1:
        local, domain = s.split("@")
        if domain in ("gmail.com", "googlemail.com"):
            local = local.replace(".", "").split("+", 1)[0]
            s = local + "@gmail.com"
    return s


def _is_valid_email(s):
    if s.count("@") != 1:
        return False
    local, domain = s.split("@")
    return (
        bool(local)
        and "." in domain
        and not domain.startswith(".")
        and not domain.endswith(".")
    )


def _normalize_phone(raw):
    m = _EXT_RE.search(raw)
    if m:
        raw = raw[:m.start()]
    digits = "".join(c for c in raw if "0" <= c <= "9")
    if len(digits) == 11 and digits[0] == "1":
        digits = digits[1:]
    return digits


def _is_valid_phone(digits):
    return len(digits) == 10 and digits[0] not in "01"


def _normalize_zip(raw):
    z = raw.strip()
    m = _ZIP4_RE.fullmatch(z)
    if m:
        z = m.group(1)
    if len(z) == 4 and _is_ascii_digits(z):
        z = "0" + z
    return z if len(z) == 5 and _is_ascii_digits(z) else ""


def _normalize_name(raw):
    s = raw.strip()
    if s.isupper() or s.islower():
        s = s.title()
    return s


def _parse_updated(raw):
    s = raw.strip()
    for fmt in _DATE_FORMATS:
        try:
            return datetime.strptime(s, fmt)
        except ValueError:
            pass
    return None


def _parse_tags(raw):
    return {t.strip().lower() for t in re.split(r"[;,]", raw) if t.strip()}


def dedupe_contacts(rows):
    # 1. Normalize each row; drop rows with neither a valid email nor a valid phone.
    recs = []
    for idx, row in enumerate(rows):
        email = _normalize_email(_get(row, "email"))
        phone = _normalize_phone(_get(row, "phone"))
        email_ok = _is_valid_email(email)
        phone_ok = _is_valid_phone(phone)
        if not email_ok and not phone_ok:
            continue

        last_name = _normalize_name(_get(row, "last_name"))
        source = _get(row, "source").strip().lower()
        recs.append({
            "idx": idx,
            "first_name": _normalize_name(_get(row, "first_name")),
            "last_name": last_name,
            "zip": _normalize_zip(_get(row, "zip")),
            "email": email if email_ok else "",
            "phone": phone if phone_ok else "",
            "source": source,
            "manual": source == "manual",
            "tags": _parse_tags(_get(row, "tags")),
            "opted_out": _get(row, "opted_out").strip().lower()
                         in ("y", "yes", "true", "1"),
            "updated": _parse_updated(_get(row, "updated")),
            "last_key": last_name.casefold(),
        })

    # 2. Group rows into people (union-find, so matching is transitive).
    parent = list(range(len(recs)))

    def find(i):
        while parent[i] != i:
            parent[i] = parent[parent[i]]
            i = parent[i]
        return i

    def union(a, b):
        ra, rb = find(a), find(b)
        if ra != rb:
            parent[max(ra, rb)] = min(ra, rb)

    first_by_email = {}
    first_by_phone_last = {}
    for i, r in enumerate(recs):
        if r["email"]:
            if r["email"] in first_by_email:
                union(first_by_email[r["email"]], i)
            else:
                first_by_email[r["email"]] = i
        if r["phone"] and r["last_key"]:
            key = (r["phone"], r["last_key"])
            if key in first_by_phone_last:
                union(first_by_phone_last[key], i)
            else:
                first_by_phone_last[key] = i

    groups = {}  # root -> member indices; ordered by each person's earliest row
    for i in range(len(recs)):
        groups.setdefault(find(i), []).append(i)

    # 3. Build one output record per person.
    def pick(members, field):
        cands = [recs[i] for i in members if recs[i][field]]
        if not cands:
            return ""
        # Stable sorts applied from least to most significant key:
        # input order, then most recent updated, then manual-first.
        cands.sort(key=lambda r: r["idx"])
        cands.sort(
            key=lambda r: r["updated"] if r["updated"] is not None else datetime.min,
            reverse=True,
        )
        cands.sort(key=lambda r: not r["manual"])
        return cands[0][field]

    output = []
    for members in groups.values():
        tags = set().union(*(recs[i]["tags"] for i in members))
        opted_out = any(recs[i]["opted_out"] for i in members)
        dates = [recs[i]["updated"] for i in members if recs[i]["updated"] is not None]
        latest = max(dates).strftime("%Y-%m-%d") if dates else ""

        output.append({
            "first_name": pick(members, "first_name"),
            "last_name": pick(members, "last_name"),
            "zip": pick(members, "zip"),
            "email": pick(members, "email"),
            "phone": pick(members, "phone"),
            "source": pick(members, "source"),
            "tags": ";".join(sorted(tags)),
            "opted_out": "Y" if opted_out else "N",
            "updated": latest,
        })

    return output
```

Some interpretation choices to check:

- **ZIP+4:** I accept a 4- or 5-digit prefix before the hyphen, so `2139-4307` becomes `02139`.
- **Unparseable `updated`:** a value that doesn't match any of the three formats is treated as older than any dated row. If no row in a group has a parseable date, `updated` is `""`.
- **Opt-outs:** because of the any-row rule, one opted-out duplicate suppresses the whole person. Before the send, I'd also filter the output for `opted_out == "Y"` as a final check.
- **Dropped rows:** rows with no valid email or phone are removed before matching, so their tags and opt-out flags don't carry into any group.
